import{_ as s,a0 as u,w as l,s as a,ao as i,I as o,a1 as n,A as p,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"一款很棒的GTK桌面主題：Arc | LCTT x X-CMD","titleTemplate":false,"description":"一款很棒的GTK桌面主題：Arc | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一款很棒的GTK桌面主題：Arc | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一款很棒的GTK桌面主題：Arc | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150603 Arc Is a Gorgeous GTK Theme for Linux Desktops","title":"一款很棒的GTK桌面主題：Arc","tag":"201506","desc":""},"relativePath":"201506/20150603 Arc Is a Gorgeous GTK Theme for Linux Desktops.md","filePath":"[post].md"}'),m={name:"201506/20150603 Arc Is a Gorgeous GTK Theme for Linux Desktops.md"};function d(T,t,g,f,h,k){const r=u("Link");return l(),a("div",null,[t[16]||(t[16]=i('<h1 id="一款很棒的gtk桌面主題-arc" tabindex="-1">一款很棒的GTK桌面主題：Arc <a class="header-anchor" href="#一款很棒的gtk桌面主題-arc" aria-label="Permalink to “一款很棒的GTK桌面主題：Arc”">​</a></h1><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/06/arc-gtk-theme.jpg" alt=""></p><p>距離本站上次推薦的GTK主題已經過了很久了。但是看到上圖中的Arc主題後，就值得打破冷場了。我們不能不推薦它！</p><h3 id="arc-gtk主題" tabindex="-1">Arc GTK主題 <a class="header-anchor" href="#arc-gtk主題" aria-label="Permalink to “Arc GTK主題”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/06/see-through-theme.png" alt=""></p><p><em>透明，並不符合每個人的口味</em></p><p>Arc是一個扁平化主題並有微妙的配色方案，窗口的選中區域是透明的，如GTK的頂欄和Nautilus的側邊欄。</p><p>它的效果不像我們之前介紹的主題那樣將程序渲染的像那麼混亂。有點像 OSX Yosemite，效果用的不多但是很好。</p><p>與之伴隨的圖標集（稱為Vertex）同樣工作的很好。</p><p><strong>是的它支持Unity</strong></p><p>Arc主題支持基於GTK3和GTK2桌面環境，包含Gnome Shell(當然了)和標準的Ubuntu Unity。</p><p>它可以很好地遊刃於輕量級的Budgie和elementary的Pantheon桌面之間，並且與Cinnamon配合也不錯。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/06/Screen-Shot-2015-06-02-at-18.07.15.png" alt=""></p><p><em>Arc中的開關、滑塊和小掛件</em></p><p>它並不容易下載與安裝- <em>understatement klaxon</em> - 因為它還在密集開發中。</p><p>安裝包需要GTK 3.14及以上，這意味着Ubuntu 14.04 LTS和14.10的用户無法使用了。</p><p>那些使用Ubuntu 15.04的用户可以使用這個主題。你可以添加ppa或者雙擊.deb包來安裝。</p><p>如果你喜歡它，你需要捲起你的袖子並查看github上的編譯指導。</p>',18)),o("ul",null,[o("li",null,[n(r,{href:"https://github.com/horst3180/Arc-theme"},{default:p(()=>[...t[0]||(t[0]=[e("Github中Arc安裝指導",-1)])]),_:1})])]),t[17]||(t[17]=o("p",null,"更新6/7：現在可以使用軟件庫來安裝它（由 openSUSE 用户 Horst1380 創建，也可用於 Ubuntu 用户），也可以下載預打包的 .deb 文件。",-1)),o("ul",null,[o("li",null,[n(r,{href:"http://software.opensuse.org/download.html?project=home%3AHorst3180&package=arc-theme"},{default:p(()=>[...t[1]||(t[1]=[e("Horst31890 的 Arc 主題庫",-1)])]),_:1})]),o("li",null,[n(r,{href:"http://download.opensuse.org/repositories/home:/Horst3180/xUbuntu_15.04/all/arc-theme_1433786431.697b2c3_all.deb"},{default:p(()=>[...t[2]||(t[2]=[e("下載 Arc 主題 .deb",-1)])]),_:1})])]),t[18]||(t[18]=o("hr",null,null,-1)),o("p",null,[t[4]||(t[4]=e("via: ",-1)),n(r,{href:"http://www.omgubuntu.co.uk/2015/06/arc-gtk-theme"},{default:p(()=>[...t[3]||(t[3]=[e("http://www.omgubuntu.co.uk/2015/06/arc-gtk-theme",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=e("作者：",-1)),n(r,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:p(()=>[...t[5]||(t[5]=[e("Joey-Elijah Sneddon",-1)])]),_:1}),t[9]||(t[9]=e(" 譯者：",-1)),n(r,{href:"https://github.com/geekpi"},{default:p(()=>[...t[6]||(t[6]=[e("geekpi",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),n(r,{href:"https://github.com/wxy"},{default:p(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[13]||(t[13]=e("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創翻譯，",-1)),n(r,{href:"https://linux.cn/"},{default:p(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const G=s(m,[["render",d]]);export{w as __pageData,G as default};
